db.orders.aggregate([
  { $project: { status: 1, total: 1, orderDate: 1 } },
  { $match: { status: "completed" } },
  { $group: { _id: "$orderDate", dailyTotal: { $sum: "$total" } } }
])

const orders = await db.collection('orders').find().toArray();
const totalRevenue = orders
  .filter(o => o.status === 'completed')
  .reduce((sum, o) => sum + o.amount, 0);

db.posts.aggregate([
  { $match: { _id: postId } },
  { $lookup: {
      from: "comments",
      localField: "_id",
      foreignField: "postId",
      as: "comments"
  }}
])

db.products.aggregate([
  { $match: { category: "electronics" } },
  // Document contains a 5MB 'manual_pdf_base64' field
  { $group: { _id: "$brand", count: { $sum: 1 } } },
  { $sort: { count: -1 } }
])
